function safeRows(nodeName){try{return $(nodeName).all().map(function(i){return i.json||{};});}catch(e){return [];}}
function esc(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
function fa2en(s){return String(s==null?'':s).replace(/[۰-۹]/g,function(d){return '۰۱۲۳۴۵۶۷۸۹'.indexOf(d);});}
function normTime(s){return fa2en(s).replace(/\s+/g,'').replace('،','').trim();}

const DAYS = ['شنبه','یکشنبه','دوشنبه','سه‌شنبه','چهارشنبه','پنجشنبه','جمعه'];
function dayRank(d){var i=DAYS.indexOf(String(d||'').trim());return i<0?99:i;}

const isLive = function(r){var s=String(r['وضعیت']||'').trim();return s!=='غیرفعال'&&s!=='حذف';};

function delForm(sheetKind, id, label){
  if (!id) return '';
  var confirmMsg = esc(label) + ' حذف شود؟ این کار قابل بازگشت نیست مگر با ثبت دوباره.';
  return '<form class="delf" method="post" action="/webhook/barnameh-farda-hazf" data-confirm="'+confirmMsg+'">'
    + '<input type="hidden" name="sheet" value="'+esc(sheetKind)+'">'
    + '<input type="hidden" name="id" value="'+esc(id)+'">'
    + '<button type="submit" class="delbtn" title="حذف">✕</button>'
    + '</form>';
}

// ============ جدول ۱: برنامهٔ هفتگی ============
const weekly = safeRows('خواندن برنامه هفتگی').filter(function(r){return isLive(r)&&(r['نام_فراگیر']||r['کد_کلاس']);});
const teachers = safeRows('خواندن مدرسین');
function teacherName(row){
  var n = String(row['نام_مدرس']||'').trim();
  if (n) return n;
  var code = String(row['کد_مدرس']||'').trim();
  if (code){ var t=teachers.filter(function(x){return String(x['کد_مدرس']).trim()===code;})[0]; if(t) return String(t['نام_مدرس']||'').trim(); }
  return '';
}

const slots = {};
const order = [];
for (var i=0;i<weekly.length;i++){
  var r = weekly[i];
  var key = [String(r['کد_کلاس']||'').trim(), String(r['روز_هفته']||'').trim(), normTime(r['ساعت_شروع']), String(r['مکان']||'').trim()].join('|');
  if (!slots[key]){
    slots[key] = {
      cls: String(r['نام_کلاس']||r['کد_کلاس']||'').trim(),
      group: String(r['شماره_گروه']||'').trim(),
      day: String(r['روز_هفته']||'').trim(),
      start: String(r['ساعت_شروع']||'').trim(),
      end: String(r['ساعت_پایان']||'').trim(),
      place: String(r['مکان']||'').trim(),
      type: String(r['نوع_کلاس']||'').trim(),
      teacher: teacherName(r),
      students: [],
      statuses: {},
    };
    order.push(key);
  }
  var nm = String(r['نام_فراگیر']||'').trim();
  var rid = String(r['شناسه']||'').trim();
  var st = String(r['وضعیت']||'').trim();
  if (nm) slots[key].students.push({ name: nm, id: rid, status: st });
  if (st && st !== 'فعال') slots[key].statuses[st] = true;
  if (!slots[key].group && r['شماره_گروه']) slots[key].group = String(r['شماره_گروه']).trim();
  if (!slots[key].teacher){ var tn=teacherName(r); if(tn) slots[key].teacher=tn; }
}

order.sort(function(a,b){
  var A=slots[a],B=slots[b];
  if (A.cls!==B.cls) return A.cls<B.cls?-1:1;
  if (A.group!==B.group) return A.group<B.group?-1:1;
  if (dayRank(A.day)!==dayRank(B.day)) return dayRank(A.day)-dayRank(B.day);
  return normTime(A.start)<normTime(B.start)?-1:1;
});

var weeklyRows = '';
var totalStudents = 0;
for (var k=0;k<order.length;k++){
  var s = slots[order[k]];
  totalStudents += s.students.length;
  var isGroup = s.students.length>1;
  var time = s.start + (s.end?(' – '+s.end):'');
  var statusTags = Object.keys(s.statuses).map(function(st){
    var cls = st === 'جبرانی' ? 'tag st-makeup' : 'tag st-other';
    return ' <span class="'+cls+'">'+esc(st)+'</span>';
  }).join('');
  var studentsHtml = s.students.length
    ? s.students.map(function(st){
        var stTag = (st.status && st.status !== 'فعال') ? (' <span class="'+(st.status==='جبرانی'?'stchip mk':'stchip')+'">'+esc(st.status)+'</span>') : '';
        return '<span class="stuchip">'+esc(st.name)+stTag+delForm('weekly', st.id, st.name)+'</span>';
      }).join('')
    : '—';
  weeklyRows += '<tr>'
    + '<td class="cls">'+esc(s.cls)+(s.type?(' <span class="tag">'+esc(s.type)+'</span>'):'')+statusTags+'</td>'
    + '<td class="grp">'+(s.group?('<span class="badge'+(isGroup?' g':'')+'">'+esc(s.group)+'</span>'):'—')+'</td>'
    + '<td>'+esc(s.day)+'</td>'
    + '<td class="num">'+esc(time||'—')+'</td>'
    + '<td>'+esc(s.place||'—')+'</td>'
    + '<td>'+esc(s.teacher||'—')+'</td>'
    + '<td class="stu">'+studentsHtml+(isGroup?(' <span class="cnt">'+s.students.length+' نفر</span>'):'')+'</td>'
    + '</tr>';
}
if (!weeklyRows) weeklyRows = '<tr><td colspan="7" class="empty">هنوز هیچ کلاسی ثبت نشده است.</td></tr>';

// ============ جدول ۲: جلسات جبرانی (از برنامه_کلاس‌ها) ============
function toSortableDate(iso){ return String(iso||'').slice(0,10); }
const sessions = safeRows('خواندن برنامه کلاس‌ها').filter(function(r){
  return isLive(r) && String(r['وضعیت']||'').trim()==='جبرانی';
});
sessions.sort(function(a,b){
  var da=toSortableDate(a['تاریخ_میلادی']), db=toSortableDate(b['تاریخ_میلادی']);
  if (da!==db) return da<db?-1:1;
  return normTime(a['ساعت'])<normTime(b['ساعت'])?-1:1;
});

var makeupRows = '';
for (var m=0;m<sessions.length;m++){
  var ms = sessions[m];
  var mid = String(ms['شناسه']||'').trim();
  var mTeacher = String(ms['نام_مدرس']||'').trim() || teacherName(ms);
  makeupRows += '<tr>'
    + '<td class="num">'+esc(ms['تاریخ_شمسی']||'—')+'</td>'
    + '<td>'+esc(String(ms['روز_هفته']||'')||'—')+'</td>'
    + '<td class="cls">'+esc(ms['نام_کلاس']||ms['کد_کلاس']||'—')+'</td>'
    + '<td>'+esc(mTeacher||'—')+'</td>'
    + '<td class="num">'+esc(ms['ساعت']||'—')+'</td>'
    + '<td>'+esc(ms['مکان']||'—')+'</td>'
    + '<td>'+esc(ms['توضیح']||'—')+'</td>'
    + '<td class="delcol">'+delForm('session', mid, 'این جلسهٔ جبرانی')+'</td>'
    + '</tr>';
}
if (!makeupRows) makeupRows = '<tr><td colspan="8" class="empty">هیچ جلسهٔ جبرانی‌ای ثبت نشده است.</td></tr>';

const now = new Date().toLocaleString('fa-IR',{timeZone:'Asia/Tehran'});

const html = '<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8">'
+ '<meta name="viewport" content="width=device-width,initial-scale=1">'
+ '<title>فهرست کلاس‌ها و گروه‌ها</title>'
+ '<style>'
+ ':root{--bg:#f6f7f9;--card:#fff;--ink:#16211f;--ink2:#5a6b66;--line:#e6ebe8;--pine:#0f5049;--pine-soft:#e4f0ee;--gold:#a9761b;--gold-soft:#f7edd8;--red:#a63a2a;--red-soft:#fae8e4}'
+ '*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Vazirmatn,Tahoma,system-ui,sans-serif;font-size:15px;line-height:1.8}'
+ '.wrap{max-width:1100px;margin:0 auto;padding:20px 16px 60px}'
+ 'h1{font-size:22px;margin:0 0 4px}h2{font-size:16px;margin:34px 0 4px}.sub{color:var(--ink2);font-size:13px;margin-bottom:18px}'
+ '.card{background:var(--card);border:1px solid var(--line);border-radius:14px;overflow:hidden;box-shadow:0 8px 24px -18px rgba(0,0,0,.3)}'
+ '.tablewrap{overflow-x:auto}table{border-collapse:collapse;width:100%;min-width:760px;font-size:14px}'
+ 'th,td{text-align:right;padding:11px 13px;border-bottom:1px solid var(--line);vertical-align:top}'
+ 'th{background:var(--pine-soft);color:var(--pine);font-weight:700;font-size:12.5px;white-space:nowrap;position:sticky;top:0}'
+ 'tr:last-child td{border-bottom:0}tbody tr:hover{background:#fafcfb}'
+ '.cls{font-weight:700}.tag{font-size:11px;color:var(--ink2);font-weight:400}'
+ '.tag.st-makeup{color:var(--gold);font-weight:700;background:var(--gold-soft);border-radius:999px;padding:1px 8px}'
+ '.tag.st-other{color:var(--ink2);background:#eef1f0;border-radius:999px;padding:1px 8px}'
+ '.num{font-variant-numeric:tabular-nums;white-space:nowrap;direction:ltr;text-align:right}'
+ '.badge{display:inline-block;background:#eef1f0;border:1px solid var(--line);border-radius:999px;padding:1px 9px;font-size:12px;font-weight:700}'
+ '.badge.g{background:var(--gold-soft);border-color:var(--gold);color:var(--gold)}'
+ '.stu{min-width:220px}.cnt{display:inline-block;margin-inline-start:6px;font-size:11px;color:var(--gold);font-weight:700}'
+ '.stuchip{display:inline-flex;align-items:center;gap:4px;background:var(--card);border:1px solid var(--line);border-radius:999px;padding:2px 4px 2px 10px;margin:2px 4px 2px 0;font-size:13px}'
+ '.stchip{font-size:10.5px;font-weight:700;color:var(--ink2);background:#eef1f0;border-radius:999px;padding:1px 7px}'
+ '.stchip.mk{color:var(--gold);background:var(--gold-soft)}'
+ '.delf{display:inline-flex;margin:0}'
+ '.delbtn{font:inherit;font-size:12px;line-height:1;width:20px;height:20px;border-radius:50%;border:1px solid var(--line);background:var(--red-soft);color:var(--red);cursor:pointer;display:inline-flex;align-items:center;justify-content:center}'
+ '.delbtn:hover{background:var(--red);color:#fff}'
+ '.delcol{text-align:center}'
+ '.empty{text-align:center;color:var(--ink2);padding:30px}'
+ '.foot{color:var(--ink2);font-size:12px;margin-top:14px;text-align:center}'
+ '.stats{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:16px}'
+ '.stat{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:10px 16px}'
+ '.stat b{font-size:20px;display:block}.stat span{font-size:12px;color:var(--ink2)}'
+ '.note{background:var(--gold-soft);border:1px solid var(--gold);border-radius:10px;padding:10px 14px;font-size:12.5px;color:var(--ink);margin-bottom:14px}'
+ '</style></head><body><div class="wrap">'
+ '<h1>فهرست کلاس‌ها و گروه‌ها</h1>'
+ '<div class="sub">برنامهٔ هفتگی آموزشگاه علمی فردا — برای مشاهده، پیش از ثبت کلاس تازه؛ کنار هر فراگیر یا جلسه می‌توانید حذف کنید. تگ طلایی «جبرانی» یعنی همان یک تایم برای جبرانی ثبت شده.</div>'
+ '<div class="stats">'
+ '<div class="stat"><b class="num">'+order.length+'</b><span>گروه/جلسه</span></div>'
+ '<div class="stat"><b class="num">'+totalStudents+'</b><span>ثبت فراگیر</span></div>'
+ '<div class="stat"><b class="num">'+sessions.length+'</b><span>جلسهٔ جبرانی رزروشده</span></div>'
+ '</div>'
+ '<div class="card"><div class="tablewrap"><table>'
+ '<thead><tr><th>کلاس</th><th>گروه</th><th>روز</th><th>ساعت</th><th>مکان</th><th>مدرس</th><th>فراگیران</th></tr></thead>'
+ '<tbody>'+weeklyRows+'</tbody></table></div></div>'
+ '<h2>جلسات جبرانی رزروشده (از فرم کلاس برگزارشده)</h2>'
+ '<div class="note">برای هر جلسهٔ جبرانی، مکان و ساعت را دقیق ثبت کنید تا با کلاس‌های دیگر تداخل نکند. این فهرست از فرم «کلاس برگزارشده» با وضعیت «جبرانی» ساخته می‌شود؛ برای ثبت یک تایمِ جبرانی در برنامهٔ هفتگی هم می‌توانید از فرم «برنامهٔ کلاسی شاگرد» با وضعیت «جبرانی» استفاده کنید — نتیجه‌اش در جدول بالا با تگ طلایی دیده می‌شود.</div>'
+ '<div class="card"><div class="tablewrap"><table>'
+ '<thead><tr><th>تاریخ</th><th>روز</th><th>کلاس</th><th>مدرس</th><th>ساعت</th><th>مکان</th><th>توضیح</th><th></th></tr></thead>'
+ '<tbody>'+makeupRows+'</tbody></table></div></div>'
+ '<div class="foot">به‌روزرسانی: '+esc(now)+' — این صفحه زنده از دفتر خوانده می‌شود. برای بستن، تب را ببندید.</div>'
+ '</div>'
+ '<script>document.querySelectorAll(".delf").forEach(function(f){f.addEventListener("submit",function(e){if(!confirm(f.getAttribute("data-confirm")))e.preventDefault();});});</script>'
+ '</body></html>';

return [{ json: { html: html } }];
